CREATE TABLE IF NOT EXISTS ops_maintenance_plans (id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON UPDATE CASCADE ON DELETE RESTRICT, wall_id TEXT NOT NULL REFERENCES living_assets(id) ON UPDATE CASCADE ON DELETE RESTRICT, service_type TEXT NOT NULL, cadence_days INTEGER NOT NULL CHECK (cadence_days BETWEEN 1 AND 365), next_due_date DATE NOT NULL, duration_minutes INTEGER NOT NULL CHECK (duration_minutes BETWEEN 15 AND 480), tasks_json JSONB NOT NULL, required_skills_json JSONB NOT NULL, status TEXT NOT NULL CHECK (status IN ('active','paused')), source TEXT NOT NULL, created_by TEXT NOT NULL, updated_by TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, UNIQUE(wall_id, service_type));
CREATE TABLE IF NOT EXISTS ops_maintenance_occurrences (plan_id TEXT NOT NULL REFERENCES ops_maintenance_plans(id) ON UPDATE CASCADE ON DELETE RESTRICT, service_date DATE NOT NULL, work_order_id TEXT NOT NULL UNIQUE REFERENCES work_orders(id) ON UPDATE CASCADE ON DELETE RESTRICT, status TEXT NOT NULL CHECK (status IN ('generated','cancelled')), generated_by TEXT NOT NULL, generated_at TIMESTAMPTZ NOT NULL, PRIMARY KEY(plan_id, service_date));
CREATE TABLE IF NOT EXISTS ops_maintenance_generation_runs (id TEXT PRIMARY KEY, from_date DATE NOT NULL, through_date DATE NOT NULL, status TEXT NOT NULL CHECK (status IN ('completed','failed')), generated_count INTEGER NOT NULL, skipped_count INTEGER NOT NULL, actor TEXT NOT NULL, started_at TIMESTAMPTZ NOT NULL, completed_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS idx_pg_maintenance_plan_due ON ops_maintenance_plans(status, next_due_date);
CREATE INDEX IF NOT EXISTS idx_pg_maintenance_occurrence_date ON ops_maintenance_occurrences(service_date, status);
INSERT INTO schema_migrations(version, applied_at) VALUES ('2026-08-31.postgres-maintenance-planning-v1', NOW()) ON CONFLICT(version) DO NOTHING;
